using System;
using UnityEngine;

public sealed class WhackAMoleController : MonoBehaviour
{
    [Serializable] private struct PosePacket { public bool rightDetected; public float rightWristX,rightWristY; }
    [Serializable] private struct MotionPacket { public float beta,gamma,ax,ay,az,rx,ry,rz; public int recenter; }
    private enum State { Intro, Countdown, Playing, Results }
    private readonly Vector2[] slots={new(.385f,.625f),new(.5f,.635f),new(.615f,.625f),new(.38f,.485f),new(.5f,.495f),new(.62f,.485f),new(.372f,.34f),new(.5f,.35f),new(.628f,.34f)};
    private MotionSession session; private State state; private GameObject table,hammer,head,hitHead; private Transform hammerPivot;
    private GameObject tablePrefab,headPrefab,hitPrefab,hammerPrefab; private Material tableMat,headMat,hitMat,hammerMat;
    private Vector2 cursorViewport=new(.5f,.5f),previousPose,activeSlot; private float downSpeed,phonePower,stateAt,endAt,nextHeadAt,headAt,headUntil,hitUntil,lastHit,centerBeta,centerGamma; private int lastRecenter; private bool phoneCalibrated,phoneHasControl;
    private int score,hits,misses,combo,bestCombo; private string message=""; private Texture2D dark,gold,red,turquoise,white; private GUIStyle title,body,scoreStyle,big;
    private Vector2 HandViewport=>cursorViewport;

    private void Awake(){session=MotionSession.Ensure();session.ConfigureForScene(SceneNavigator.WhackAMole);LoadAssets();BuildScene();previousPose=new Vector2(.5f,.5f);stateAt=Time.time;}
    private Material Mat(Texture2D t,string n){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")??Shader.Find("Standard")){name=n,mainTexture=t,color=Color.white};return m;}
    private void LoadAssets(){const string r="Jungle/NewModels/WhackAMole/",tr=r+"Meshy_AI_model_20261026_texture_fbx/",hr=r+"Meshy_AI_Cheeky_Monkey_20261026_texture_fbx/",ir=r+"Meshy_AI_Dizzy_Monkey_20261026_texture_fbx/",mr=r+"Meshy_AI_Wooden_War_Drum_20261026_texture_fbx/";tablePrefab=Resources.Load<GameObject>(tr+"Meshy_AI_model_20261026_texture");headPrefab=Resources.Load<GameObject>(hr+"Meshy_AI_Cheeky_Monkey_20261026_texture");hitPrefab=Resources.Load<GameObject>(ir+"Meshy_AI_Dizzy_Monkey_20261026_texture");hammerPrefab=Resources.Load<GameObject>(mr+"Meshy_AI_Wooden_War_Drum_20261026_texture");tableMat=Mat(Resources.Load<Texture2D>(tr+"Meshy_AI_model_20261026_texture"),"Mesa");headMat=Mat(Resources.Load<Texture2D>(hr+"Meshy_AI_Cheeky_Monkey_20261026_texture"),"Cabeza");hitMat=Mat(Resources.Load<Texture2D>(ir+"Meshy_AI_Dizzy_Monkey_20261026_texture"),"Golpeado");hammerMat=Mat(Resources.Load<Texture2D>(mr+"Meshy_AI_Wooden_War_Drum_20261026_texture"),"Mazo");}

    private void BuildScene(){Camera c=Camera.main;c.orthographic=false;c.fieldOfView=48;c.transform.position=new(0,3.15f,-11.2f);c.transform.LookAt(new Vector3(0,-.65f,.25f));c.backgroundColor=new(.08f,.18f,.13f);var bg=GameObject.CreatePrimitive(PrimitiveType.Quad);bg.name="01 Fondo";bg.transform.position=new(0,1.2f,7.2f);bg.transform.localScale=new(31,17.4f,1);bg.GetComponent<Collider>().enabled=false;var bm=new Material(Shader.Find("Unlit/Texture")){mainTexture=Resources.Load<Texture2D>("Jungle/NewModels/WhackAMole/WhackAMoleBackground")};bg.GetComponent<Renderer>().sharedMaterial=bm;
        table=Model(tablePrefab,tableMat,"02 Mesa cara superior",new Vector3(0,-.75f,.28f),9.35f,true,Quaternion.Euler(-63,0,0));hammer=Model(hammerPrefab,hammerMat,"04 Mazo",World(HandViewport,7.7f),2.35f,false,Quaternion.Euler(8,180,-38));hammerPivot=hammer.transform.Find("Pivote visual");var l=FindAnyObjectByType<Light>();if(l!=null){l.intensity=1.5f;l.transform.rotation=Quaternion.Euler(42,-25,0);}}
    private Vector3 World(Vector2 v,float d)=>Camera.main.ViewportToWorldPoint(new Vector3(v.x,v.y,d));
    private GameObject Model(GameObject prefab,Material mat,string n,Vector3 pos,float size,bool width,Quaternion rot){var root=new GameObject(n);root.transform.SetParent(transform);root.transform.position=pos;var pivot=new GameObject("Pivote visual");pivot.transform.SetParent(root.transform,false);if(prefab==null){Debug.LogError("Falta "+n);return root;}var model=Instantiate(prefab,pivot.transform);model.name="Modelo";model.transform.SetLocalPositionAndRotation(Vector3.zero,rot);model.transform.localScale=Vector3.one;foreach(var c in model.GetComponentsInChildren<Collider>(true))c.enabled=false;var rs=model.GetComponentsInChildren<Renderer>(true);if(rs.Length==0)return root;Bounds b=BoundsOf(rs);float measure=width?b.size.x:Mathf.Max(b.size.x,b.size.y);model.transform.localScale=Vector3.one*(size/Mathf.Max(.01f,measure));b=BoundsOf(rs);model.transform.position+=pos-b.center;foreach(var r in rs){r.enabled=true;r.gameObject.layer=0;var ms=r.sharedMaterials;for(int i=0;i<ms.Length;i++)ms[i]=mat;r.sharedMaterials=ms;}return root;}
    private static Bounds BoundsOf(Renderer[] rs){Bounds b=rs[0].bounds;for(int i=1;i<rs.Length;i++)b.Encapsulate(rs[i].bounds);return b;}

    private void Update(){ReadInput();MoveHammer();if(state==State.Countdown&&Time.time-stateAt>=3)StartRound();else if(state==State.Playing){if(Time.time>=endAt)Finish();else UpdateHead();}}
    private static float DeadZone(float value,float radius){float a=Mathf.Abs(value);return a<=radius?0:Mathf.Sign(value)*(a-radius);}
    private void ReadInput(){if(session.TryConsumePose(out string p)){var pose=JsonUtility.FromJson<PosePacket>(p);if(pose.rightDetected){Vector2 next=new(pose.rightWristX,pose.rightWristY);float dt=Mathf.Max(.01f,Time.deltaTime);downSpeed=Mathf.Lerp(downSpeed,(next.y-previousPose.y)/dt,.4f);previousPose=next;if(!phoneHasControl){Vector2 cameraTarget=new(next.x,1f-next.y);cursorViewport=Vector2.Lerp(cursorViewport,cameraTarget,Mathf.Clamp01(10f*Time.deltaTime));}}}if(session.TryConsumeMotion(out string m)){var q=JsonUtility.FromJson<MotionPacket>(m);phonePower=Mathf.Max(0,(new Vector3(q.ax,q.ay,q.az).magnitude-9.81f)*18f)+new Vector3(q.rx,q.ry,q.rz).magnitude;if(!phoneCalibrated||q.recenter!=lastRecenter){centerBeta=q.beta;centerGamma=q.gamma;lastRecenter=q.recenter;phoneCalibrated=true;phoneHasControl=true;cursorViewport=new Vector2(.5f,.5f);}float side=DeadZone(Mathf.DeltaAngle(centerGamma,q.gamma),2.2f);float vertical=DeadZone(Mathf.DeltaAngle(centerBeta,q.beta),2.2f);Vector2 phoneTarget=new(Mathf.Clamp01(.5f+side/70f),Mathf.Clamp01(.5f-vertical/56f));cursorViewport=Vector2.Lerp(cursorViewport,phoneTarget,Mathf.Clamp01(9f*Time.deltaTime));}}
    private void MoveHammer(){if(hammer==null)return;hammer.transform.position=Vector3.Lerp(hammer.transform.position,World(HandViewport,7.7f),22*Time.deltaTime);float s=Mathf.Clamp01(Mathf.Max(downSpeed/2.2f,phonePower/260));if(hammerPivot!=null)hammerPivot.localRotation=Quaternion.Slerp(hammerPivot.localRotation,Quaternion.Euler(0,0,Mathf.Lerp(0,68,s)),20*Time.deltaTime);if(state==State.Playing&&head!=null&&Time.time-lastHit>.22f&&(downSpeed>.72f||phonePower>235))TryHit();}
    private void SpawnHead(){activeSlot=slots[UnityEngine.Random.Range(0,slots.Length)];head=Model(headPrefab,headMat,"03 Cabeza activa",World(activeSlot+Vector2.down*.075f,10.45f),1.42f,false,Quaternion.Euler(0,180,0));headAt=Time.time;headUntil=Time.time+1.25f;message="¡AHORA!";}
    private void UpdateHead(){if(hitHead!=null&&Time.time>=hitUntil){Destroy(hitHead);hitHead=null;nextHeadAt=Time.time+UnityEngine.Random.Range(.18f,.48f);}if(head==null&&hitHead==null&&Time.time>=nextHeadAt)SpawnHead();if(head==null)return;float age=Time.time-headAt,remaining=headUntil-Time.time,pop=Mathf.SmoothStep(0,1,Mathf.Clamp01(age/.18f));if(remaining<.18f)pop=Mathf.SmoothStep(0,1,Mathf.Clamp01(remaining/.18f));head.transform.position=World(activeSlot+Vector2.down*Mathf.Lerp(.075f,0,pop),10.45f);if(Time.time>=headUntil){Destroy(head);head=null;misses++;combo=0;message="¡SE ESCAPÓ!";nextHeadAt=Time.time+.28f;}}
    private void TryHit(){if(Time.time-headAt<.14f||Vector2.Distance(HandViewport,activeSlot)>.105f)return;lastHit=Time.time;Destroy(head);head=null;hitHead=Model(hitPrefab,hitMat,"03 Cabeza golpeada",World(activeSlot,10.35f),1.52f,false,Quaternion.Euler(0,180,UnityEngine.Random.Range(-7,7)));hitUntil=Time.time+.42f;hits++;combo++;bestCombo=Mathf.Max(bestCombo,combo);int gain=100+Mathf.Min(combo,12)*20;score+=gain;message=combo>=4?$"¡COMBO x{combo}!":$"+{gain}";}
    private void Begin(){score=hits=misses=combo=bestCombo=0;phoneCalibrated=false;cursorViewport=new Vector2(.5f,.5f);state=State.Countdown;stateAt=Time.time;}
    private void StartRound(){state=State.Playing;endAt=Time.time+45;nextHeadAt=Time.time+.35f;message="¡A JUGAR!";}
    private void Finish(){if(head!=null)Destroy(head);if(hitHead!=null)Destroy(hitHead);head=hitHead=null;state=State.Results;message="¡TIEMPO!";}

    private Texture2D Solid(Color c){var t=new Texture2D(1,1);t.SetPixel(0,0,c);t.Apply();return t;}
    private void UI(){if(dark!=null&&title!=null&&body!=null&&scoreStyle!=null&&big!=null)return;dark=Solid(new(.01f,.045f,.035f,.94f));gold=Solid(new(1,.75f,.08f,.96f));red=Solid(new(.9f,.08f,.03f,.95f));turquoise=Solid(new(.03f,.82f,.78f,.95f));white=Solid(Color.white);title=new GUIStyle(GUI.skin.label){fontSize=Mathf.RoundToInt(Screen.height*.055f),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter,normal={textColor=new(1,.82f,.15f)}};body=new GUIStyle(GUI.skin.label){fontSize=Mathf.RoundToInt(Screen.height*.028f),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter,wordWrap=true,normal={textColor=Color.white}};scoreStyle=new GUIStyle(body){fontSize=Mathf.RoundToInt(Screen.height*.037f)};big=new GUIStyle(title){fontSize=Mathf.RoundToInt(Screen.height*.1f),normal={textColor=Color.white}};}
    private void OnGUI(){JungleUITheme.Ensure();UI();float w=Screen.width,h=Screen.height;GUI.DrawTexture(new Rect(w*.02f,h*.02f,w*.96f,h*.105f),dark);GUI.Label(new Rect(w*.04f,h*.025f,w*.34f,h*.085f),"GORILLA WHACK",title);GUI.Label(new Rect(w*.39f,h*.028f,w*.38f,h*.075f),$"PUNTOS {score}   COMBO x{combo}",scoreStyle);if(GUI.Button(new Rect(w*.84f,h*.035f,w*.12f,h*.065f),"MENÚ",JungleUITheme.Button))SceneNavigator.Load(SceneNavigator.MainMenu);
        if(state==State.Intro){GUI.DrawTexture(new Rect(w*.25f,h*.23f,w*.5f,h*.48f),dark);GUI.Label(new Rect(w*.29f,h*.27f,w*.42f,h*.09f),"¡ATRAPA AL GORILA!",title);GUI.Label(new Rect(w*.3f,h*.38f,w*.4f,h*.13f),"INCLINA EL CELULAR PARA APUNTAR\nY HAZ UN GOLPE HACIA ABAJO",body);if(GUI.Button(new Rect(w*.38f,h*.58f,w*.24f,h*.08f),"CENTRAR Y JUGAR",JungleUITheme.Button))Begin();}
        else if(state==State.Countdown){int c=Mathf.Clamp(3-Mathf.FloorToInt(Time.time-stateAt),1,3);GUI.DrawTexture(new Rect(w*.42f,h*.31f,w*.16f,h*.2f),dark);GUI.Label(new Rect(w*.42f,h*.31f,w*.16f,h*.2f),c.ToString(),big);}else if(state==State.Playing){GUI.DrawTexture(new Rect(w*.43f,h*.14f,w*.14f,h*.065f),endAt-Time.time<6?red:dark);GUI.Label(new Rect(w*.43f,h*.14f,w*.14f,h*.065f),Mathf.CeilToInt(Mathf.Max(0,endAt-Time.time))+" s",scoreStyle);}else{GUI.DrawTexture(new Rect(w*.28f,h*.25f,w*.44f,h*.42f),dark);GUI.Label(new Rect(w*.32f,h*.29f,w*.36f,h*.08f),"RESULTADO",title);GUI.Label(new Rect(w*.32f,h*.39f,w*.36f,h*.14f),$"{score} PUNTOS\n{hits} GOLPES · {misses} ESCAPES · MEJOR COMBO x{bestCombo}",body);if(GUI.Button(new Rect(w*.36f,h*.56f,w*.18f,h*.07f),"OTRA RONDA",JungleUITheme.Button))Begin();}
        if(state==State.Playing)GUI.Label(new Rect(w*.36f,h*.2f,w*.28f,h*.065f),message,body);float s=Mathf.Max(28,h*.045f);Vector2 p=HandViewport;Rect cursor=new(p.x*w-s*.5f,(1-p.y)*h-s*.5f,s,s);GUI.DrawTexture(cursor,white);GUI.DrawTexture(new Rect(cursor.x+5,cursor.y+5,cursor.width-10,cursor.height-10),turquoise);JungleUITheme.DrawLeaves();}
}
